import urllib.request
import urllib.error
import time

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path
        req = urllib.request.Request(url)
        req.add_header('Accept', 'application/json')
        try:
            response = urllib.request.urlopen(req, timeout=self.timeout)
            return response.read().decode('utf-8')
        except urllib.error.URLError as e:
            if isinstance(e.reason, urllib.error.HTTPError):
                if e.code == 429:
                    for i in range(3):
                        if i > 0:
                            time.sleep(2 ** i - 1)
                        try:
                            response = urllib.request.urlopen(req, timeout=self.timeout)
                            return response.read().decode('utf-8')
                        except urllib.error.HTTPError as he:
                            if he.code != 429:
                                raise ClientError(f'Rate limit still not cleared after retries: {he}')
                elif e.code == 5xx:
                    time.sleep(1)
                    try:
                        response = urllib.request.urlopen(req, timeout=self.timeout)
                        return response.read().decode('utf-8')
                    except urllib.error.HTTPError as he:
                        raise ServerError(f'Server error still not cleared after retry: {he}')
            else:
                raise ConnectionError(f'Network error: {e.reason}')
        except urllib.error.HTTPError as e:
            if e.code == 429:
                for i in range(3):
                    if i > 0:
                        time.sleep(2 ** i - 1)
                    try:
                        response = urllib.request.urlopen(req, timeout=self.timeout)
                        return response.read().decode('utf-8')
                    except urllib.error.HTTPError as he:
                        if he.code != 429:
                            raise RateLimitError(f'Rate limit still not cleared after retries: {he}')
            elif 500 <= e.code < 600:
                time.sleep(1)
                try:
                    response = urllib.request.urlopen(req, timeout=self.timeout)
                    return response.read().decode('utf-8')
                except urllib.error.HTTPError as he:
                    raise ServerError(f'Server error still not cleared after retry: {he}')
            else:
                raise ClientError(f'Client error: {e.code}')
        except Exception:
            time.sleep(1)
            try:
                response = urllib.request.urlopen(req, timeout=self.timeout)
                return response.read().decode('utf-8')
            except urllib.error.URLError as e:
                raise ConnectionError(f'Connection error still not cleared after retry: {e.reason}')
